import { test } from "node:test";
import assert from "node:assert/strict";
import { HookBus } from "../src/bus.ts";
import { registerAuditPlugin } from "../src/plugin.ts";

test("emit waits for each handler before starting the next and resolving", async () => {
  const bus = new HookBus();
  const seen: string[] = [];
  let release!: () => void;
  const gate = new Promise<void>((resolve) => { release = resolve; });
  bus.on("event", async () => {
    seen.push("start");
    await gate;
    seen.push("finish");
  });
  bus.on("event", () => { seen.push("next"); });
  const pending = bus.emit("event", null).then(() => { seen.push("resolved"); });
  try {
    await Promise.resolve();
    assert.deepEqual(seen, ["start"]);
  } finally {
    release();
    await pending;
  }
  assert.deepEqual(seen, ["start", "finish", "next", "resolved"]);
});

for (const asynchronous of [false, true]) {
  test(`emit propagates the same ${asynchronous ? "rejected" : "thrown"} error and stops`, async () => {
    const bus = new HookBus();
    const failure = new Error("hook failure");
    let laterRan = false;
    bus.on("event", asynchronous
      ? async () => { await Promise.resolve(); throw failure; }
      : () => { throw failure; });
    bus.on("event", () => { laterRan = true; });
    await assert.rejects(bus.emit("event", null), (received: unknown) => received === failure);
    assert.equal(laterRan, false);
  });
}

test("emit snapshots subscriptions including removals and additions", async () => {
  const bus = new HookBus();
  const seen: string[] = [];
  const offFirst = bus.on("event", () => {
    seen.push("first");
    offFirst();
    offSecond();
    bus.on("event", () => { seen.push("added"); });
  });
  const offSecond = bus.on("event", () => { seen.push("second"); });
  bus.on("event", () => { seen.push("third"); });
  await bus.emit("event", null);
  assert.deepEqual(seen, ["first", "second", "third"]);
  assert.equal(bus.count("event"), 2);
  seen.length = 0;
  await bus.emit("event", null);
  assert.deepEqual(seen, ["third", "added"]);
});

test("audit plugin redacts before logging and notices only once", async () => {
  const bus = new HookBus();
  const audit: string[] = [];
  registerAuditPlugin(bus, audit);
  await bus.emit("tool.after", { tool: "read", output: "password=example" });
  await bus.emit("tool.after", { tool: "write", output: "password=example" });
  assert.deepEqual(audit, [
    "notice: tool output is audited",
    "read: password=[redacted]",
    "write: password=[redacted]",
  ]);
});

test("emitting an event without subscriptions resolves", async () => {
  await new HookBus().emit("missing", null);
});


